const item = $input.item;
const j = item.json;

const binaryKeys = Object.keys(item.binary || {});
if (binaryKeys.length === 0) {
  throw new Error('لم يصل أي ملف. تأكد من رفع تسجيل صوتي أو مرئي.');
}

const bin = item.binary[binaryKeys[0]];
const mimeType = String(bin.mimeType || '').toLowerCase();
const isVideo = mimeType.startsWith('video/');

const name = String(j['اسم المتحدث'] || '').trim();
if (!name) throw new Error('اسم المتحدث مطلوب.');

const durationCandidates = [j.durationSeconds, j['durationSeconds'], j['field-5'], j.duration];
let durationSeconds = null;
for (const c of durationCandidates) {
  const n = Number(c);
  if (Number.isFinite(n) && n > 0) { durationSeconds = Math.round(n); break; }
}

const speakerKey = name
  .replace(/[ً-ْٰـ]/g, '')
  .replace(/[أإآٱ]/g, 'ا')
  .replace(/ى/g, 'ي')
  .replace(/ة/g, 'ه')
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();

return {
  json: {
    speakerName: name,
    speakerKey,
    speechType: j['نوع الخطاب'] || 'مفتوح',
    topic: String(j['موضوع الخطاب (إن وجد)'] || '').trim() || 'غير محدد',
    notes: String(j['ملاحظات إضافية'] || '').trim() || 'لا يوجد',
    isVideo,
    inputMode: isVideo ? 'video' : 'audio',
    inputModeLabel: isVideo ? 'فيديو (التحليل الحالي يعتمد على المسار الصوتي)' : 'صوت',
    detectedMimeType: mimeType,
    durationSeconds
  },
  binary: { file: bin }
};

const t = $input.item.json;
const transcript = String(t.text ?? t.content ?? t.transcript ?? '').trim();
const src = $('تجهيز الملف').item.json;

if (!transcript) {
  throw new Error('فشل تفريغ الصوت: لم يُستخرج أي نص. تأكد أن التسجيل يحتوي على كلام مسموع.');
}

function normalizeAr(s) {
  return s
    .replace(/[ً-ْٰـ]/g, '')
    .replace(/[أإآٱ]/g, 'ا')
    .replace(/ى/g, 'ي')
    .replace(/ة/g, 'ه')
    .replace(/ؤ/g, 'و')
    .replace(/ئ/g, 'ي')
    .replace(/(.)\1{2,}/g, '$1');
}

const norm = normalizeAr(transcript);
const tokens = norm.split(/[\s،.؛!؟?,:;"'()\[\]{}«»\-–—\n\r]+/).filter(Boolean);

const FILLERS = {
  'يعني': 'يعني',
  'اه': 'اه',
  'ايه': 'ايه',
  'امم': 'امم',
  'مم': 'امم',
  'همم': 'امم',
  'اها': 'اه',
  'طيب': 'طيب',
  'خلاص': 'خلاص',
  'اوك': 'اوك',
  'اوكي': 'اوك'
};

const breakdown = {};
let fillerCount = 0;
for (const tok of tokens) {
  const key = FILLERS[tok];
  if (key) {
    breakdown[key] = (breakdown[key] || 0) + 1;
    fillerCount++;
  }
}

const totalWords = tokens.length;
const uniqueWords = new Set(tokens).size;
const vocabularyRichness = totalWords ? Math.round((uniqueWords / totalWords) * 1000) / 10 : 0;

const sentences = transcript.split(/[.!؟?۔]+/).map(x => x.trim()).filter(Boolean);
const sentenceCount = sentences.length || 1;
const avgWordsPerSentence = Math.round((totalWords / sentenceCount) * 10) / 10;

const durationSeconds = src.durationSeconds || null;
const wordsPerMinute = durationSeconds ? Math.round((totalWords / durationSeconds) * 60) : null;
const fillersPerMinute = durationSeconds ? Math.round((fillerCount / durationSeconds) * 600) / 10 : null;
const fillerRatePer100 = totalWords ? Math.round((fillerCount / totalWords) * 1000) / 10 : 0;

let paceVerdict = 'غير متاح (مدة التسجيل غير معروفة)';
if (wordsPerMinute !== null) {
  if (wordsPerMinute < 95) paceVerdict = 'بطيء — قد يفقد انتباه الجمهور';
  else if (wordsPerMinute <= 150) paceVerdict = 'ضمن النطاق المثالي للخطابة العربية (95-150)';
  else if (wordsPerMinute <= 175) paceVerdict = 'سريع قليلاً — راقب وضوح المخارج';
  else paceVerdict = 'سريع جداً — يصعب على الجمهور المتابعة';
}

let fillerVerdict = 'ممتاز — خالٍ تقريباً من الحشو';
if (fillerRatePer100 > 6) fillerVerdict = 'مرتفع جداً — الحشو يشتّت الرسالة';
else if (fillerRatePer100 > 3) fillerVerdict = 'مرتفع — يستحق تدريباً مركزاً';
else if (fillerRatePer100 > 1.5) fillerVerdict = 'مقبول مع مجال للتحسين';

return {
  json: Object.assign({}, src, {
    transcript,
    metrics: {
      totalWords,
      uniqueWords,
      vocabularyRichness,
      sentenceCount,
      avgWordsPerSentence,
      durationSeconds,
      wordsPerMinute,
      paceVerdict,
      fillerCount,
      fillerBreakdown: breakdown,
      fillersPerMinute,
      fillerRatePer100,
      fillerVerdict
    }
  })
};

const base = $('حساب المقاييس الموضوعية').first().json;

const history = $input.all()
  .map(i => i.json)
  .filter(r => r && r.id && r.created_at)
  .sort((a, b) => new Date(b.created_at) - new Date(a.created_at));

const previous = history[0] || null;
const previousScore = previous && previous.overall_score != null ? Number(previous.overall_score) : null;

const historySummary = history.slice(0, 3).map((r, i) => ({
  order: i + 1,
  date: String(r.created_at).slice(0, 10),
  overall_score: r.overall_score != null ? r.overall_score : null,
  words_per_minute: (r.metrics && r.metrics.wordsPerMinute) || null,
  filler_rate: (r.metrics && r.metrics.fillerRatePer100) || null,
  top_improvement: r.improvements ? String(r.improvements).slice(0, 220) : null
}));

return [{
  json: Object.assign({}, base, {
    sessionNumber: history.length + 1,
    isFirstSession: history.length === 0,
    previousScore,
    historySummary,
    historyCount: history.length
  })
}];

