function parseJson(v) {
  if (v && typeof v === 'object') return v;
  try {
    const s = String(v).trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
    return JSON.parse(s);
  } catch (e) {
    return null;
  }
}

const ctx = $('تجميع السياق').item.json;
const evalRaw = $('الوكيل المقيّم - تحليل منهجي').item.json;
const coachRaw = $input.item.json;

const ev = parseJson(evalRaw.content != null ? evalRaw.content : (evalRaw.text != null ? evalRaw.text : evalRaw.output_text));
const co = parseJson(coachRaw.content != null ? coachRaw.content : (coachRaw.text != null ? coachRaw.text : coachRaw.output_text));

if (!ev || !ev.scores) throw new Error('تعذر قراءة نتيجة التقييم المنهجي.');
if (!co) throw new Error('تعذر قراءة تقرير التدريب.');

const m = ctx.metrics;
const s = ev.scores;
const overall = Number(s.overall) || 0;
const delta = ctx.previousScore != null ? overall - Number(ctx.previousScore) : null;

function bar(n) {
  const filled = Math.max(0, Math.min(10, Math.round(n / 10)));
  return '█'.repeat(filled) + '░'.repeat(10 - filled);
}

const L = [];
L.push('📊 التقييم: الوضوح ' + s.clarity + ' · البنية ' + s.structure + ' · الجذب ' + s.engagement + ' · اللغة ' + s.language + ' · الإيقاع ' + s.vocal_delivery + ' · الثقة ' + s.confidence + ' · الإجمالي ' + overall);
L.push('');
L.push(co.headline);
L.push('');
L.push('【 الدرجات 】');
L.push('وضوح الرسالة   ' + bar(s.clarity) + '  ' + s.clarity);
L.push('تماسك البنية   ' + bar(s.structure) + '  ' + s.structure);
L.push('جذب الجمهور    ' + bar(s.engagement) + '  ' + s.engagement);
L.push('سلامة اللغة    ' + bar(s.language) + '  ' + s.language);
L.push('الإيقاع الصوتي ' + bar(s.vocal_delivery) + '  ' + s.vocal_delivery);
L.push('الثقة والحضور  ' + bar(s.confidence) + '  ' + s.confidence);
L.push('');
L.push('الدرجة الإجمالية: ' + overall + '/100' + (delta != null ? '  (' + (delta >= 0 ? '▲ +' + delta : '▼ ' + delta) + ' عن الجلسة السابقة)' : '  - جلستك الأولى'));
L.push('');
L.push('【 مقاييس موضوعية 】');
L.push('عدد الكلمات: ' + m.totalWords + ' | كلمات فريدة: ' + m.uniqueWords + ' (ثراء ' + m.vocabularyRichness + '%)');
L.push('سرعة الكلام: ' + (m.wordsPerMinute != null ? m.wordsPerMinute + ' كلمة/دقيقة' : 'غير متاحة') + ' - ' + m.paceVerdict);
L.push('التلكؤات: ' + m.fillerCount + ' مرة (' + m.fillerRatePer100 + ' لكل 100 كلمة) - ' + m.fillerVerdict);
if (Object.keys(m.fillerBreakdown || {}).length) {
  L.push('تفصيل: ' + Object.keys(m.fillerBreakdown).map(function (k) { return k + ' x' + m.fillerBreakdown[k]; }).join(' · '));
}
L.push('متوسط طول الجملة: ' + m.avgWordsPerSentence + ' كلمة عبر ' + m.sentenceCount + ' جملة');
L.push('');
L.push('【 بصمتك الأسلوبية 】');
L.push('« ' + co.style_signature.title + ' »');
L.push(co.style_signature.description);
L.push('');
L.push('【 بنية الخطاب 】');
L.push('المقدمة: ' + ev.structure_analysis.introduction);
L.push('صلب الموضوع: ' + ev.structure_analysis.body);
L.push('الخاتمة: ' + ev.structure_analysis.conclusion);
L.push('الانسيابية: ' + ev.structure_analysis.flow_notes);
L.push('');
L.push('【 نقاط التميز 】');
(co.strengths || []).forEach(function (x, i) {
  L.push((i + 1) + '. ' + x.title);
  L.push('   ' + x.detail);
  if (x.evidence) L.push('   الدليل: "' + x.evidence + '"');
});
L.push('');
L.push('【 أولويات التطوير 】');
(co.priority_improvements || []).forEach(function (x, i) {
  L.push((i + 1) + '. ' + x.title);
  L.push('   لماذا: ' + x.why);
  L.push('   كيف: ' + x.how);
  if (x.evidence) L.push('   الدليل: "' + x.evidence + '"');
});
L.push('');
L.push('【 خطة التدريب الأسبوعية 】');
(co.practice_plan || []).forEach(function (p) {
  L.push('• ' + p.day + ' (' + p.duration_minutes + ' دقيقة) - ' + p.target_skill);
  L.push('  ' + p.exercise);
});
L.push('');
if (ev.language_analysis && (ev.language_analysis.grammar_issues || []).length) {
  L.push('【 تصويبات لغوية 】');
  ev.language_analysis.grammar_issues.forEach(function (g) { L.push('• ' + g.issue + '  ←  ' + g.correction); });
  L.push('');
}
L.push('【 وسائل الجذب 】');
L.push('استخدمت: ' + ((ev.rhetoric_analysis.techniques_used || []).join('، ') || 'لم ترصد وسائل جذب واضحة'));
L.push('مقترح إضافتها: ' + ((ev.rhetoric_analysis.techniques_missing || []).join('، ') || '-'));
L.push('');
if ((ev.red_flags || []).length) {
  L.push('【 تنبيهات 】');
  ev.red_flags.forEach(function (r) { L.push('⚠ ' + r); });
  L.push('');
}
L.push('【 تتبع التطور 】');
L.push(co.progress_note);
L.push('');
L.push('【 تحدي الجلسة القادمة 】');
L.push(co.next_session_challenge);
L.push('');
L.push(co.motivational_close);
L.push('');
L.push('ℹ ' + ev.delivery_analysis.visual_note);

return {
  json: {
    speaker_name: ctx.speakerName,
    speaker_key: ctx.speakerKey,
    speech_type: ctx.speechType,
    topic: ctx.topic,
    input_mode: ctx.inputMode,
    detected_mime_type: ctx.detectedMimeType,
    transcript: ctx.transcript,
    notes: ctx.notes,
    session_number: ctx.sessionNumber,
    duration_seconds: m.durationSeconds,
    overall_score: overall,
    progress_delta: delta,
    scores: s,
    metrics: m,
    coaching_plan: co,
    verbal_analysis: {
      structure: ev.structure_analysis,
      language: ev.language_analysis,
      rhetoric: ev.rhetoric_analysis,
      evidence: ev.evidence_quotes,
      red_flags: ev.red_flags
    },
    nonverbal_analysis: ev.delivery_analysis,
    style_signature: co.style_signature.title + ' - ' + co.style_signature.description,
    strengths: (co.strengths || []).map(function (x) { return '• ' + x.title + ': ' + x.detail; }).join('\n'),
    improvements: (co.priority_improvements || []).map(function (x) { return '• ' + x.title + ' - ' + x.how; }).join('\n'),
    full_report: L.join('\n'),
    analysis_version: 'v2'
  }
};
